<?php require_once __DIR__ . '/../includes/functions.php'; admin_header('Cases'); $rows=db_fetch_all('SELECT pc.*,p.full_name,p.phone FROM patient_cases pc JOIN patients p ON p.id=pc.patient_id ORDER BY pc.id DESC LIMIT 100'); ?><div class="card soft-card"><div class="card-body table-responsive"><table class="table"><thead><tr><th>Case</th><th>Patient</th><th>Status</th><th>Doctor</th><th>Emergency</th><th></th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= e($r['case_code']) ?></td><td><?= e($r['full_name']) ?><br><small><?= e($r['phone']) ?></small></td><td><?= e($r['status']) ?></td><td><?= e($r['doctor_status']) ?></td><td><?= $r['emergency_flag']?'Yes':'No' ?></td><td><a class="btn btn-sm btn-outline-success" href="case-view.php?id=<?= (int)$r['id'] ?>">View</a></td></tr><?php endforeach; ?></tbody></table><?php if(!$rows) echo empty_state('No cases yet.'); ?></div></div><?php admin_footer(); ?>
